/* ── NWS Terminal runtime prologue ─────────────────────────────────
   Vendor libs are loaded on demand. Leaflet (42 KB gz) is only needed by
   RADAR; Chart.js (69 KB gz) only by HOURLY / MODELS / SOUNDING. Loading
   them in <head> cost 112 KB gz + ~350 ms of parse on every cold load,
   0% of it used at first paint.
   ────────────────────────────────────────────────────────────────── */
var VENDOR = {
  leaflet: { js: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js',
             css: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css',
             ready: function(){ return typeof L !== 'undefined'; } },
  chart:   { js: 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js',
             ready: function(){ return typeof Chart !== 'undefined'; } }
};
var _vendorP = {};
function loadVendor(name) {
  var v = VENDOR[name];
  if (!v) return Promise.resolve();
  if (v.ready()) return Promise.resolve();
  if (_vendorP[name]) return _vendorP[name];
  _vendorP[name] = new Promise(function (res, rej) {
    if (v.css) {
      var l = document.createElement('link');
      l.rel = 'stylesheet'; l.href = v.css; document.head.appendChild(l);
    }
    var sc = document.createElement('script');
    sc.src = v.js; sc.async = true;
    sc.onload = function(){ res(); };
    sc.onerror = function(){ _vendorP[name] = null; rej(new Error(name + ' failed to load')); };
    document.head.appendChild(sc);
  });
  return _vendorP[name];
}

/* Intl.DateTimeFormat was reconstructed ~350x per fetch (once per table row).
   Constructing a formatter is ~100x the cost of using one. */
/* Same-origin proxy for NOAA hosts that send no CORS header. Replaces
   corsproxy.io / api.allorigins.win — third-party relays that could observe
   every request and return arbitrary bodies into innerHTML sinks. */
/* Precipitation unit factors, by model. The original guessed from the data
   (`maxPrecip > 1 ? mm : metres`), so a forecast whose total stayed under
   1 mm picked the metres factor and rendered a 0.4 mm trace as 15.7 INCHES.
   GribStream returns GFS/NBM/RRFS/RAP APCP as kg/m2 (= mm) and ECMWF/AIFS
   `tp` as metres. That is a property of the model, not of the values. */
/* /points was fetched twice and the station list three times per location,
   and two of those used the pre-redirect URL form so they each paid a 301.
   doFetch resolves both once and everything else reads from here. */
var _nwsPoints = null;      // properties object from /points
var _stationsURL = null;    // post-redirect /gridpoints/{cwa}/{x},{y}/stations

async function nwsStationsURL(lat, lon) {
  if (_stationsURL) return _stationsURL;
  if (_nwsPoints && _nwsPoints.gridId && _nwsPoints.gridX != null) {
    _stationsURL = 'https://api.weather.gov/gridpoints/' + _nwsPoints.gridId + '/' +
                   _nwsPoints.gridX + ',' + _nwsPoints.gridY + '/stations';
    return _stationsURL;
  }
  var r = await netFetch('https://api.weather.gov/points/' + lat + ',' + lon,
                      { headers: { 'Accept': 'application/geo+json' } });
  if (!r.ok) throw new Error('Points API: HTTP ' + r.status);
  var d = await r.json();
  _nwsPoints = d.properties;
  _stationsURL = d.properties.observationStations;
  return _stationsURL;
}

var PRECIP_TO_IN = { mm: 0.03937, m: 39.3701 };
var MODEL_PRECIP_UNIT = {
  gfs: 'mm', nbm: 'mm', hrrr: 'mm', rrfs: 'mm', rap: 'mm',
  ecmwf: 'm', aifs: 'm', graphcast: 'm', fourcast: 'm'
};
function precipFactor(model, data) {
  var u = MODEL_PRECIP_UNIT[model];
  if (u) return PRECIP_TO_IN[u];
  // Unknown model: fall back to the old heuristic, but only when there is
  // enough signal for it to mean anything.
  var mx = 0;
  (data || []).forEach(function (r) { if (r.precip != null && r.precip > mx) mx = r.precip; });
  return mx > 1 ? PRECIP_TO_IN.mm : PRECIP_TO_IN.m;
}

/* Nominatim REQUIRES a User-Agent and returns 403 without one — and
   `User-Agent` is a forbidden header name, so the browser silently drops the
   one this app tried to set. Geocoding was therefore entirely at Nominatim's
   discretion. Routing it through our own server lets us send a real UA.
   Falls back to calling Nominatim directly if the proxy route isn't there
   (e.g. the file opened straight off disk). */
var _geoProxyOK = null;

/* Nominatim also rate-limits hard (429) under its usage policy. Open-Meteo's
   geocoder needs no key, sends CORS headers, has no User-Agent requirement,
   and this app already depends on Open-Meteo for AQI and climate — so it is
   the natural fallback. Results are normalised to Nominatim's shape so the
   callers don't care which one answered. */
async function geoOpenMeteo(query, limit) {
  var r = await netFetch('https://geocoding-api.open-meteo.com/v1/search?name=' +
    encodeURIComponent(query) + '&count=' + (limit || 1) +
    '&countryCode=US&language=en&format=json');
  if (!r.ok) return [];
  var d = await r.json();
  return (d.results || []).map(function (x) {
    return {
      lat: String(x.latitude), lon: String(x.longitude),
      display_name: [x.name, x.admin1, x.country_code].filter(Boolean).join(', '),
      type: x.feature_code === 'AIRP' ? 'aerodrome' : (x.feature_code || ''),
      class: x.feature_code === 'AIRP' ? 'aeroway' : ''
    };
  });
}

async function geoSearch(params, query, limit) {
  var qs = 'format=json&countrycodes=us&' + params;
  if (_geoProxyOK !== false) {
    try {
      var r = await netFetch('/p/geo/search?' + qs);
      if (r.ok) {
        var j = await r.json();
        _geoProxyOK = true;
        if (j && j.length) return j;
      } else if (r.status === 404) {
        _geoProxyOK = false;             // no proxy route on this host
      }
    } catch (e) { _geoProxyOK = false; }
  } else {
    try {
      var d = await netFetch('https://nominatim.openstreetmap.org/search?' + qs);
      if (d.ok) {
        var dj = await d.json();
        if (dj && dj.length) return dj;
      }
    } catch (e) { /* fall through */ }
  }
  try { return await geoOpenMeteo(query, limit); }
  catch (e) {
    // Both geocoders down/rate-limited: say so, instead of a bare "Failed to fetch".
    throw new Error('Place search is busy right now. Try again in a minute, or use an airport code (e.g. KBOI) or "lat, lon".');
  }
}

function px(url) {
  var m = String(url).match(/^https?:\/\/(?:www\.)?(spc\.noaa\.gov|cpc\.ncep\.noaa\.gov|wpc\.ncep\.noaa\.gov|aviationweather\.gov|digital\.weather\.gov|mapservices\.weather\.noaa\.gov|api\.elections\.kalshi\.com|nowcoast\.noaa\.gov|opengeo\.ncep\.noaa\.gov|data\.cocorahs\.org)\/(.*)$/);
  if (!m) return url;
  var kind = { 'spc.noaa.gov':'spc', 'cpc.ncep.noaa.gov':'cpc',
               'wpc.ncep.noaa.gov':'wpc', 'aviationweather.gov':'awc', 'digital.weather.gov':'ndfd',
               'mapservices.weather.noaa.gov':'nwsmap', 'api.elections.kalshi.com':'kalshi', 'nowcoast.noaa.gov':'nowcoast', 'opengeo.ncep.noaa.gov':'opengeo', 'data.cocorahs.org':'cocorahs' }[m[1]];
  return '/p/' + kind + '/' + m[2];
}

var _dtfCache = {};
function locDTF(opts) {
  var key = (locTimezone || '~') + '|' + JSON.stringify(opts);
  if (!_dtfCache[key]) {
    var o = {};
    for (var k in opts) o[k] = opts[k];
    if (locTimezone) o.timeZone = locTimezone;
    _dtfCache[key] = new Intl.DateTimeFormat('en-US', o);
  }
  return _dtfCache[key];
}

/* Calendar date AT THE LOCATION (not the browser, not UTC). Several panels
   used toISOString() — a UTC date — so after 00Z (7 PM CDT, 5 PM PDT) they
   asked for the wrong day. */
function locYMD(offsetDays) {
  var d = new Date(Date.now() + (offsetDays || 0) * 864e5);
  var o = { year: 'numeric', month: '2-digit', day: '2-digit' };
  if (locTimezone) o.timeZone = locTimezone;
  var parts = {};
  new Intl.DateTimeFormat('en-US', o).formatToParts(d).forEach(function (p) { parts[p.type] = p.value; });
  return { y: +parts.year, m: +parts.month, d: +parts.day };
}
function locHourNow() {
  var o = { hour: 'numeric', hourCycle: 'h23' };
  if (locTimezone) o.timeZone = locTimezone;
  return +new Intl.DateTimeFormat('en-US', o).format(new Date()) % 24;
}
function locDateStr(offsetDays) {
  var t = locYMD(offsetDays);
  return t.y + '-' + String(t.m).padStart(2, '0') + '-' + String(t.d).padStart(2, '0');
}

/* NOAA/Meeus sunrise equation. Returns Date objects (UTC instants) for the
   given LOCAL calendar date. lon east-positive. */

/* Markup → plain text with entities decoded. DOMParser documents are inert
   (no script execution, no resource loads). */
function htmlToText(html) {
  try { return (new DOMParser().parseFromString(String(html), 'text/html').body.textContent || '').trim(); }
  catch (e) { return String(html).replace(/<[^>]+>/g, '').trim(); }
}

/* NWS heat index (full algorithm: Steadman simple form below 80 °F-ish,
   Rothfusz regression with the low-RH and high-RH adjustments above) and
   NWS 2001 wind chill. The bare regression was off by up to 2 °F. */
function heatIndexF(T, RH) {
  if (T == null || RH == null) return null;
  var s = 0.5 * (T + 61 + (T - 68) * 1.2 + RH * 0.094);
  if ((s + T) / 2 < 80) return s;
  var hi = -42.379 + 2.04901523*T + 10.14333127*RH - 0.22475541*T*RH - 0.00683783*T*T
         - 0.05481717*RH*RH + 0.00122874*T*T*RH + 0.00085282*T*RH*RH - 0.00000199*T*T*RH*RH;
  if (RH < 13 && T >= 80 && T <= 112) hi -= ((13 - RH) / 4) * Math.sqrt((17 - Math.abs(T - 95)) / 17);
  else if (RH > 85 && T >= 80 && T <= 87) hi += ((RH - 85) / 10) * ((87 - T) / 5);
  return hi;
}
function windChillF(T, mph) {
  if (T == null || mph == null || T > 50 || mph < 3) return null;
  var v = Math.pow(mph, 0.16);
  return 35.74 + 0.6215 * T - 35.75 * v + 0.4275 * T * v;
}
/* Rounded apparent temperature, or null when neither index applies. */
function feelsLikeF(T, RH, mph) {
  if (T == null) return null;
  if (T <= 50) { var wc = windChillF(T, mph); return wc != null && Math.round(wc) < T ? Math.round(wc) : null; }
  if (T >= 80 && RH != null) { var hi = heatIndexF(T, RH); return Math.round(hi) > T ? Math.round(hi) : null; }
  return null;
}

/* METAR present-weather + sky cover → NWS-style plain English. */
var WX_CODES = { RA:'Rain', SN:'Snow', DZ:'Drizzle', TS:'Thunderstorm', SH:'Showers', FZ:'Freezing',
  PL:'Ice Pellets', GR:'Hail', GS:'Small Hail', SG:'Snow Grains', IC:'Ice Crystals', UP:'Precipitation',
  BR:'Mist', FG:'Fog', HZ:'Haze', FU:'Smoke', DU:'Dust', SA:'Sand', VA:'Volcanic Ash', SQ:'Squalls',
  FC:'Funnel Cloud', BL:'Blowing', DR:'Drifting', MI:'Shallow', BC:'Patches of', PR:'Partial', VC:'Nearby' };
function metarText(wx, clouds) {
  if (wx && String(wx).trim()) {
    return String(wx).trim().split(/\s+/).map(function (tok) {
      var inten = tok[0] === '-' ? 'Light ' : tok[0] === '+' ? 'Heavy ' : '';
      var body = tok.replace(/^[-+]/, '');
      var words = [];
      for (var i = 0; i < body.length; i += 2) { var w = WX_CODES[body.substr(i, 2)]; if (w) words.push(w); }
      if (words[0] === 'Thunderstorm' && words.length > 1) words.splice(1, 0, 'with');
      return words.length ? inten + words.join(' ') : tok;
    }).join(', ');
  }
  var rank = { SKC: 0, CLR: 0, CAVOK: 0, NSC: 0, FEW: 1, SCT: 2, BKN: 3, OVC: 4, OVX: 5, VV: 5 };
  var best = -1;
  (clouds || []).forEach(function (c) { var r = rank[c && c.cover]; if (r != null && r > best) best = r; });
  return ['Clear', 'A Few Clouds', 'Partly Cloudy', 'Mostly Cloudy', 'Overcast', 'Sky Obscured'][best] || '';
}

/* Escape untrusted strings before they reach innerHTML. Data arriving via
   third-party CORS relays is attacker-mutable and must never be trusted. */
function esc(v) {
  if (v == null) return '';
  return String(v).replace(/[&<>"']/g, function (c) {
    return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
  });
}

/* Sequence guard: Enter-key and favorite clicks bypass the disabled FETCH
   button, so two runs could interleave over the same globals and render a
   mix of two cities. */
var _fetchSeq = 0;

// Location time once a location is loaded (every other time in the UI is
// location-local), with its zone; aligned to the minute boundary.
function updateClock() {
  var o = { hour: 'numeric', minute: '2-digit' };
  if (typeof locTimezone !== 'undefined' && locTimezone) { o.timeZone = locTimezone; o.timeZoneName = 'short'; }
  var el = document.getElementById('clock');
  try { el.textContent = new Date().toLocaleTimeString('en-US', o); }
  catch (e) { el.textContent = new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }); }
}
(function tick() { updateClock(); setTimeout(tick, 60000 - Date.now() % 60000 + 50); })();

/* Full-size image viewer. #spcLightbox shipped without an <img>, so every
   click on an SPC/CPC map threw a TypeError and nothing opened. */
function openLightbox(src, alt) {
  var lb = document.getElementById('spcLightbox');
  if (!lb) return;
  var im = lb.querySelector('img');
  if (!im) { im = document.createElement('img'); lb.appendChild(im); }
  im.src = src;                 // keep the query: proxied URLs need it for cache-keying
  im.alt = alt || 'Full-size map';
  lb.classList.add('open');
  lb._opener = document.activeElement;
  var c = lb.querySelector('.lb-close'); if (c) c.focus();
}
function closeLightbox() {
  var lb = document.getElementById('spcLightbox');
  if (!lb || !lb.classList.contains('open')) return;
  lb.classList.remove('open');
  if (lb._opener && lb._opener.focus) lb._opener.focus();
}

// ---- SPC OUTLOOK IMAGE LOADER ----
// The unsuffixed files (day1otlk.png, day2probotlk_torn.png, day3prob.png …)
// are always the latest issuance. The old code guessed timestamped names from
// a fixed schedule that only held in standard time: from March to November it
// served a Day 2 image frozen on Mar 8 and a Day 3 image frozen on Mar 7.
// Routed through the same-origin proxy (edge-cached 10 min) with a 10-minute
// nonce instead of Date.now(), which defeated every cache on every visit.
function loadSPCImages() {
  var base = 'https://www.spc.noaa.gov/products/outlook/';
  var nonce = '?v=' + Math.floor(Date.now() / 600000);
  var names = ['day1otlk','day1probotlk_torn','day1probotlk_wind','day1probotlk_hail',
               'day2otlk','day2probotlk_torn','day2probotlk_wind','day2probotlk_hail',
               'day3otlk','day3prob'];
  var map = {};
  names.forEach(function (n) { map[n] = px(base + n + '.png') + nonce; });

  document.querySelectorAll('img[data-spc]').forEach(function(img) {
    var key = img.getAttribute('data-spc');
    var url = map[key];
    if (url) {
      img.setAttribute('data-live', base + key + '.png');
      // Make clickable to open full-size in lightbox
      img.style.cursor = 'pointer';
      img.onclick = function() { openLightbox(this.src, this.alt); };
    }
  });
}
loadSPCImages();

// SPC image retry with alternate URLs for broken static images
var spcRetryAlts = {
  'sfc': [
    'https://www.wpc.ncep.noaa.gov/sfc/namussfc12wbg.gif?v=' + Math.floor(Date.now() / 600000),
    'https://www.wpc.ncep.noaa.gov/sfc/namussfcwbg.gif'
  ]
};

function spcRetryImg(img) {
  var type = img.getAttribute('data-spc-retry');
  var attempts = img._retryN || 0;
  var urls = spcRetryAlts[type] || [];
  if (attempts < urls.length) {
    img._retryN = attempts + 1;
    img.src = urls[attempts];
  } else {
    img.onerror = null;
    img.style.display = 'none';
    if (img.parentElement) {
      img.parentElement.insertAdjacentHTML('beforeend', '<div class="cpc-err">Image unavailable</div>');
    }
  }
}


// Attach onerror to retry images, and catch ones that already failed
document.querySelectorAll('img[data-spc-retry]').forEach(function(img) {
  img.onerror = function() { spcRetryImg(this); };
  // If image already failed before script ran
  if (img.complete && img.naturalWidth === 0) {
    spcRetryImg(img);
  }
});

// Add onerror to ALL other static SPC/CPC images
document.querySelectorAll('#section-spc img.cpc-map, #section-cpc img.cpc-map').forEach(function(img) {
  if (!img.hasAttribute('data-spc') && !img.hasAttribute('data-spc-retry') && !img.onerror) {
    img.onerror = function() { spcFallbackErr(this); };
    // If already failed
    if (img.complete && img.naturalWidth === 0 && img.src.indexOf('data:image') < 0) {
      spcFallbackErr(img);
    }
  }
});

// Make ALL SPC section images clickable to open full-size
document.querySelectorAll('#section-spc img.cpc-map').forEach(function(img) {
  if (!img.hasAttribute('data-spc')) {
    img.style.cursor = 'pointer';
    img.onclick = function() { openLightbox(this.src, this.alt); };
  }
});

// Make ALL CPC section images clickable to open in lightbox
document.querySelectorAll('#section-cpc img.cpc-map, #section-wpc img.cpc-map').forEach(function(img) {
  img.style.cursor = 'pointer';
  img.onclick = function() { openLightbox(this.src, this.alt); };
});

// (Enter-to-fetch is wired once, in DOMContentLoaded. It used to be wired
// twice, so every Enter ran two overlapping fetches.)


// ---- UPGRADE: FAVORITES ----
function getFavorites() {
  try { return JSON.parse(localStorage.getItem('nws_favorites') || '[]'); }
  catch(e) { return []; }
}
function saveFavorites(favs) { localStorage.setItem('nws_favorites', JSON.stringify(favs)); if (typeof USNOW !== 'undefined') USNOW.touch(); if (typeof PUSHUI !== 'undefined') PUSHUI.touch(); }
function renderFavorites() {
  // Built with the DOM API: the saved name used to go into innerHTML and an
  // inline onclick string (a quote or backslash broke it), and "remove" was
  // a span nested inside the button — unreachable by keyboard.
  var favs = typeof favSorted === 'function' ? favSorted() : getFavorites();
  var bar = document.getElementById('favoritesBar');
  bar.textContent = '';
  if (!favs.length) { renderEmptyRecents(); return; }
  var lab = document.createElement('button'); lab.type = 'button'; lab.className = 'fav-label fav-label-btn'; lab.textContent = 'Edit saved places'; lab.title = 'Sort and manage saved places';
  lab.addEventListener('click', function () { if (typeof PLACES !== 'undefined') PLACES.open(); });
  var sc = document.createElement('div'); sc.className = 'fav-scroll';
  favs.forEach(function (loc, i) {
    var wrap = document.createElement('span'); wrap.className = 'fav-chip';
    var b = document.createElement('button'); b.type = 'button'; b.className = 'fav-btn'; b.textContent = loc;
    b.addEventListener('click', function () { loadFavorite(loc); });
    var x = document.createElement('button'); x.type = 'button'; x.className = 'fav-remove'; x.textContent = '\u00D7';
    x.setAttribute('aria-label', 'Remove ' + loc); x.title = 'Remove';
    x.addEventListener('click', function () { if (typeof removeFavoriteByName === 'function') removeFavoriteByName(loc); else removeFavorite(i); });
    wrap.appendChild(b); wrap.appendChild(x); sc.appendChild(wrap);
  });
  bar.appendChild(lab); bar.appendChild(sc);
  renderEmptyRecents();
}
function updateFavButton() {
  var loc = document.getElementById('locationInput').value.trim();
  var btn = document.getElementById('favToggle');
  var favs = getFavorites();
  var isFav = favs.some(function(f) { return f.toLowerCase() === loc.toLowerCase(); });
  btn.classList.toggle('is-fav', isFav);
  btn.setAttribute('aria-pressed', isFav ? 'true' : 'false');
  btn.title = isFav ? 'Remove from favorites' : 'Save to favorites';
}
function toggleFavorite() {
  var loc = document.getElementById('locationInput').value.trim();
  if (!loc) return;
  var favs = getFavorites();
  var idx = favs.findIndex(function(f) { return f.toLowerCase() === loc.toLowerCase(); });
  if (idx >= 0) { favs.splice(idx, 1); } else { if (favs.length >= 30) favs.pop(); favs.unshift(loc); }
  saveFavorites(favs);
  renderFavorites();
  updateFavButton();
}
function removeFavorite(i) {
  var favs = getFavorites(); favs.splice(i, 1);
  saveFavorites(favs); renderFavorites(); updateFavButton();
}
function loadFavorite(loc) {
  if (typeof favTouch === 'function') { favTouch(loc); if (favSortMode() === 'recent') renderFavorites(); }
  document.getElementById('locationInput').value = loc;
  doFetch();
}
document.getElementById('locationInput').addEventListener('input', updateFavButton);
renderFavorites();
updateFavButton();

// ---- UPGRADE: HOURLY CHARTS ----
var tempChartInstance = null;
var precipChartInstance = null;

var _hourlyPending = false;
var _hourlyPeriods = null;
var _lazyDone = {};

// ---- UPGRADE: AIR QUALITY ----

// ---- UPGRADE: SUN & MOON ----


var forecastPeriods = [];
var activeTab = 0;
var locSunrise = null;  // Date object - today's sunrise for this location
var locSunset = null;   // Date object - today's sunset for this location
var locTimezone = null; // IANA timezone e.g. 'America/New_York'

function show(id) { document.getElementById(id).classList.remove('hidden'); }
function hide(id) { document.getElementById(id).classList.add('hidden'); }
function setStep(t) { document.getElementById('loadingSub').textContent = t; }

// Format a Date in the location's timezone
function fmtLocTime(d, opts) {
  if (!d) return '--';
  var o = opts || { hour: 'numeric', minute: '2-digit' };
  if (locTimezone) o.timeZone = locTimezone;
  try { return d.toLocaleTimeString('en-US', o); }
  catch(e) { return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }); }
}

// Date + time at the location, with zone label ("Sep 28, 7:05 PM CDT").
// Alert and product times used bare toLocaleString(), i.e. the DEVICE's zone
// with no label — an Eastern iPad showed a Denver warning expiring 2h late.
function fmtIssued(v) {
  if (!v) return '';
  var d = v instanceof Date ? v : new Date(v);
  if (isNaN(d)) return String(v);
  var o = { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' };
  if (locTimezone) o.timeZone = locTimezone;
  try { return d.toLocaleString('en-US', o); } catch (e) { return d.toLocaleString(); }
}

// Get the current hour in the location's timezone
function getLocHour(d) {
  if (!d) return 12;
  if (locTimezone) {
    try {
      var s = d.toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: locTimezone });
      return parseInt(s);
    } catch(e) {}
  }
  return d.getHours();
}

function switchSection(name) {
  if (name === 'satellite') name = 'radar';   // v3.44.0: one screen, Radar and satellite; old links still land
  if (name === 'forecast' && typeof RADAROV !== 'undefined') { var _rv = RADAROV._state(); if (_rv.data && Date.now() - _rv.at > 5 * 60000) RADAROV.refresh(false); }
  if (name === 'forecast' && typeof NEXTPX !== 'undefined') NEXTPX.refresh(false);   // v3.77.0: kept ten minutes
  if (typeof HOME !== 'undefined' && HOME.on() && !HOME.leaveFor(name)) return;   // the US map is up: show the loaded place, or stay if there is none
  SECTIONS.forEach(function(s) {
    var el = document.getElementById('section-' + s);
    if (el) {
      if (s === name) {
        el.classList.remove('hidden');
        el.classList.add('entering');
        setTimeout(function() { el.classList.remove('entering'); }, 350);
      } else {
        el.classList.add('hidden');
        el.classList.remove('entering');
      }
    }
  });
  document.querySelectorAll('.nav-item[data-section]').forEach(function(btn) {
    var grp = btn.getAttribute('data-group'), on = btn.getAttribute('data-section') === name || !!(grp && (' ' + grp + ' ').indexOf(' ' + name + ' ') >= 0);
    btn.classList.toggle('active', on);
    if (on) btn.setAttribute('aria-current', 'page'); else btn.removeAttribute('aria-current');
  });
  _currentSection = name;
  if (typeof SECTABS !== 'undefined') SECTABS.note(name);
  var _re = document.getElementById('resultsEl'); if (_re) _re.setAttribute('data-sec', name);
  if (name === 'astro' && _astroArgs) renderAstro();
  if (name === 'hourly') HOURLY.draw();
  if (name === 'spc' || name === 'cpc' || name === 'wpc') refreshProductImages('section-' + name);
  writeHash();
  // Stop animations belonging to the section we just left. Neither of these
  // was ever cleared: the satellite loop kept swapping 590 KB JPEGs at 2.5 Hz
  // and the radar loop kept restyling 16 tile layers, both forever.
  if (name !== 'satellite' && satFrameInterval) {
    clearInterval(satFrameInterval); satFrameInterval = null; satFramePlaying = false;
    setPlayBtn('satPlayBtn', false);
  }
  if (name !== 'radar' && radarInterval) { stopRadarPlay(); }
  if (name === 'maps') MAPS.show(); else MAPS.hide();
  if (name === 'cams') CAMS.ensure();
  if (name === 'regional') REGMAP.ensure();
  if (name === 'upper') UAMAP.show(); else if (typeof UAMAP !== 'undefined') UAMAP.stop();   // v3.71.0
  if (name === 'spc' || name === 'wpc' || name === 'cpc') OLMAP.show(name);
  if (name === 'tropical' && typeof TROP !== 'undefined') TROP.show(false);   // v3.79.0
  if (name !== 'radar') HRMAP.leave('radar');
  if (name !== 'satellite') HRMAP.leave('satellite');
  if (name === 'radar' || name === 'satellite') HRMAP.show(name);
  if (window.innerWidth <= 720) {
    var sb = document.getElementById('sidebar'); if (sb) sb.classList.remove('open');
  }
  if (name === 'radar') {
    loadVendor('leaflet').then(function(){
    setTimeout(function() {
      if (!radarMap && currentLat && currentLon) {
        // First time showing radar — init now that container is visible
        initRadar(currentLat, currentLon);
      } else if (radarMap) {
        radarMap.invalidateSize();
        // Re-show the current frame to force tile reload
        if (radarLayers.length > 0) {
          showRadarFrame(radarIdx);
        }
      }
    }, 150);
    }).catch(function(e){
      var rm = document.getElementById('radarMap');
      if (rm) rm.innerHTML = '<div class="cpc-err">Map library failed to load. Check your connection.</div>';
    });
  }
  if (name === 'satellite') {
    setTimeout(function() {
      if (currentLat && currentLon && satFrames.length === 0) {
        initSat(currentLat, currentLon);
      }
    }, 150);
  }
  if (name === 'models') {
    if (currentLat && currentLon && gsAvailable()) {
      var mTab = document.querySelector('#modelsSubNav .gs-sub-btn.active');
      var tabName = mTab ? mTab.textContent.trim() : 'GFS';
      triggerModelsTabLoad(tabName);
    } else if (!gsAvailable()) {
      // Was "Fetch a location first..." even with a location loaded — the
      // real blocker was the missing token.
      document.querySelectorAll('#section-models [id^="gs"][id$="Loading"]').forEach(function (el) {
        el.innerHTML = 'Model guidance needs a free GribStream API token. ' +
          '<button type="button" class="btn-link" onclick="openDrawer()">Add it in Settings &amp; keys \u2192</button>';
        el.classList.remove('hidden');
      });
    }
  }
  if (name === 'hourly' && _hourlyPending) { _hourlyPending = false; renderHourlyCharts(_hourlyPeriods); }
  // Each flag holds the location it was loaded for, not just 'done': a tab opened while the next location is still
  // loading fetches the old one, and must load again once the new one is in.
  var _lk = currentLat + ',' + currentLon;
  if (name === 'regional' && currentLat && _lazyDone.regional !== _lk) { _lazyDone.regional = _lk; fetchRegional(currentLat, currentLon); }
  if (name === 'aqi'      && currentLat && _lazyDone.aqi !== _lk) { _lazyDone.aqi = _lk; fetchAQI(currentLat, currentLon); }
  if (name === 'afd'      && window._afdOffice && _lazyDone.afd !== window._afdOffice) { _lazyDone.afd = window._afdOffice; fetchAFD(window._afdOffice); }
  if (name === 'climate'  && currentLat && _lazyDone.cli !== _lk) { _lazyDone.cli = _lk; fetchCLI(currentLat, currentLon); }
  if (name === 'climate') {
    if (currentLat && currentLon && !climateLoaded) {
      fetchClimate(currentLat, currentLon);
    }
  }
  if (name === 'spc') {
    // Was: reload on every visit with ?v=Date.now(), re-downloading ~3 MB and
    // defeating the HTTP cache. Outlooks are issued on a fixed schedule, so a
    // 10-minute bucket is always fresh and cacheable in between.
    var mark = Math.floor(Date.now() / 600000);
    if (loadSPCImages._mark !== mark) { loadSPCImages._mark = mark; loadSPCImages(); }
  }
  if (name === 'kalshi') {
    if (window._wethrStation && !window._wethrLoaded) {
      window._wethrLoaded = true;
      fetchWethr(window._wethrStation);
    }
    if (window._wethrStation && wethrAvailable()) {
      if (!wethrPollMode && !wethrSSE) {
        connectWethrStream(window._wethrStation);
      } else if (wethrPollTimer) {
        // Speed up to 15s when on KALSHI tab
        clearInterval(wethrPollTimer);
        wethrPollTimer = setInterval(window._wethrPollFn, 15000);
      }
    }
  } else {
    // Slow to 60s when on other tabs (but keep polling for alerts)
    if (wethrPollTimer && window._wethrPollFn) {
      clearInterval(wethrPollTimer);
      wethrPollTimer = setInterval(window._wethrPollFn, 60000);
    }
  }
}

/* Replaces the emoji set. Emoji render at different sizes and baselines per
   platform and read as consumer-app; these inherit currentColor and align. */
var WX_ICON = (function () {
  var w = function (d) {
    return '<svg class="wx" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
      'stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + d + '</svg>';
  };
  var cloud = '<path d="M17.5 18a4.5 4.5 0 1 0 0-9h-1.8A7 7 0 1 0 4 15.7"/>';
  return {
    sun:     w('<circle cx="12" cy="12" r="4.2"/><path d="M12 2.2v2.1m0 15.4v2.1M4.1 4.1l1.5 1.5m12.8 12.8 1.5 1.5M2.2 12h2.1m15.4 0h2.1M5.6 18.4l-1.5 1.5M19.9 4.1l-1.5 1.5"/>'),
    moon:    w('<path d="M12 3.2a6.6 6.6 0 0 0 8.8 8.8A9 9 0 1 1 12 3.2Z"/>'),
    pcloud:  w('<path d="M12.5 4.5a4 4 0 0 1 3.9 3.1M8 5.5 6.8 4.3M4.6 9.5H3M8.5 2.6V1"/>' + cloud),
    cloud:   w(cloud),
    rain:    w(cloud + '<path d="M9 20.5 8 22.5M13 20.5l-1 2M17 20.5l-1 2"/>'),
    tstorm:  w(cloud + '<path d="M12 15.5 9.5 20h3.4L11 24"/>'),
    snow:    w(cloud + '<path d="M9 20h.01M12.5 21.5h.01M16 20h.01M10.5 22.5h.01M14.5 22.5h.01"/>'),
    fog:     w('<path d="M4 9h13M6.5 13h13M4 17h11"/>'),
    wind:    w('<path d="M12.8 19.6A2 2 0 1 0 14 16H2M17.5 8a2.5 2.5 0 1 1 2 4H2M9.8 4.4A2 2 0 1 1 11 8H2"/>'),
    hot:     w('<path d="M14 4a2 2 0 0 0-4 0v10.5a4 4 0 1 0 4 0Z"/><path d="M12 8v7"/>')
  };
})();

/* v3.57.0: the colour icon the week strip draws for a forecast or sky wording; the line icon if that module is missing. */
function wxColor(text, night, pop) { return typeof HOURLY !== 'undefined' && HOURLY.wkIcon ? HOURLY.wkIcon(text, night, pop) : getEmoji(text, night); }
function getEmoji(f, isNight) {
  f = (f || '').toLowerCase();
  if (f.includes('thunder') || f.includes('tstm')) return WX_ICON.tstorm;
  if (f.includes('snow') || f.includes('blizzard') || f.includes('flurr')) return WX_ICON.snow;
  if (f.includes('sleet') || f.includes('ice') || f.includes('freez')) return WX_ICON.snow;
  if (f.includes('rain') || f.includes('shower') || f.includes('drizzle')) return WX_ICON.rain;
  if (f.includes('fog') || f.includes('mist') || f.includes('haze')) return WX_ICON.fog;
  if (f.includes('overcast')) return WX_ICON.cloud;
  if (f.includes('mostly cloudy')) return WX_ICON.cloud;
  if (f.includes('partly')) return isNight ? WX_ICON.cloud : WX_ICON.pcloud;
  if (f.includes('mostly sunny') || f.includes('mostly clear') || f.includes('few clouds') || f.includes('fair')) return isNight ? WX_ICON.moon : WX_ICON.pcloud;
  if (f.includes('sunny') || f.includes('clear')) return isNight ? WX_ICON.moon : WX_ICON.sun;
  if (f.includes('wind')) return WX_ICON.wind;
  if (f.includes('hot') || f.includes('heat')) return WX_ICON.hot;
  return WX_ICON.cloud;
}

// Exact ASOS/station coordinates for Kalshi/ForecastEx/Polymarket weather markets
// Verified against metar-taf.com, weather.gladstonefamily.net, and NWS CF6/CLI products
