  KATL: { lat: 33.6301, lon: -84.4419, name: 'Atlanta Hartsfield (KATL)' },        // CLI: CLIATL
  KLAS: { lat: 36.0840, lon: -115.1537, name: 'Las Vegas McCarran (KLAS)' },        // CLI: CLILAS
  KBOS: { lat: 42.3656, lon: -71.0096, name: 'Boston Logan (KBOS)' },              // CLI: CLIBOS
  KSEA: { lat: 47.4502, lon: -122.3088, name: 'Seattle-Tacoma (KSEA)' },           // CLI: CLISEA
  KPHX: { lat: 33.4373, lon: -112.0078, name: 'Phoenix Sky Harbor (KPHX)' },       // CLI: CLIPHX
