  KHOU: { lat: 29.6454, lon: -95.2789, name: 'Houston Hobby (KHOU)' },             // CLI: CLIHOU
  KDAL: { lat: 32.8471, lon: -96.8517, name: 'Dallas Love Field (KDAL)' },         // CLI: CLIDAL — NOT DFW
  KSFO: { lat: 37.6213, lon: -122.3790, name: 'San Francisco Intl (KSFO)' },       // CLI: CLISFO
