var chatHistory = [];
var chatOpen = false;
var chatGen = 0;   // v3.72.0: bumped by New conversation, so a reply still on its way to the old one is dropped

/* v3.72.0: New conversation. Clears the thread on screen and the history sent with the next question; the open tab is
   read afresh with every question anyway, so nothing else carries over. */
function newChat() {
  chatGen++; chatHistory.length = 0;
  var m = document.getElementById('chatMessages'); if (m) m.innerHTML = '';
  var b = document.getElementById('chatSendBtn'); if (b) b.disabled = false;
  sendChatMessage._busy = false;
  var i = document.getElementById('chatInput'); if (i) { i.value = ''; i.focus(); }
}

function toggleChat() {
  chatOpen = !chatOpen;
  document.getElementById('chatPanel').classList.toggle('hidden', !chatOpen);
  if (chatOpen) document.getElementById('chatInput').focus();
}

function getActiveSection() {
  // Was 'airquality' (element is #section-aqi) and 'kalshi' was missing
  // entirely, so on those tabs the assistant was told it was on FORECAST.
  var sections = SECTIONS;
  for (var i = 0; i < sections.length; i++) {
    var el = document.getElementById('section-' + sections[i]);
    if (el && !el.classList.contains('hidden')) return sections[i];
  }
  return 'forecast';
}

function gatherScreenContext() {
  var section = getActiveSection();
  var ctx = 'Current location: ' + (document.getElementById('locName') ? document.getElementById('locName').textContent : 'Unknown') + '\n';
  var officeEl = document.getElementById('locOffice');
  if (officeEl && officeEl.textContent) ctx += 'NWS Office: ' + officeEl.textContent + '\n';
  ctx += 'Active section: ' + section.toUpperCase() + '\n';
  ctx += 'Current time at the location: ' + fmtIssued(new Date()) + '\n\n';

  try {
    if (section === 'forecast') {
      var fc = document.getElementById('section-forecast');
      if (fc) ctx += 'NWS Forecast:\n' + fc.innerText.substring(0, 15000);

    } else if (section === 'afd') {
      var afd = document.querySelector('.afd-text');
      if (afd) ctx += 'Area Forecast Discussion:\n' + afd.innerText.substring(0, 24000);

    } else if (section === 'hourly') {
      var ht = document.querySelector('#section-hourly .hourly-table');
      if (ht) ctx += 'Hourly data (first 20 rows):\n' + ht.innerText.substring(0, 10000);

    } else if (section === 'radar') {
      ctx += 'Radar section is open (live radar map). No text data — ask about current precipitation patterns, storm tracking, or radar interpretation.\n';
      // Grab any active alerts for context
      var alertsEl = document.getElementById('section-alerts');
      if (alertsEl) { var at = alertsEl.innerText.trim(); if (at.length > 30) ctx += 'Active alerts for context:\n' + at.substring(0, 5000); }

    } else if (section === 'satellite') {
      var satMode = 'unknown';
      var activeBtn = document.querySelector('#section-satellite .cpc-nav-btn.active');
      if (activeBtn) satMode = activeBtn.textContent.trim();
      ctx += 'Satellite section is open showing ' + satMode + ' imagery. Ask about cloud patterns, storm systems, or satellite interpretation.\n';

    } else if (section === 'maps') {
      ctx += 'Maps section is open: an embedded Windy map showing ' + MAPS.describe() + '. The map is a picture in a frame; its values are not readable here.\n';

    } else if (section === 'cams') {
      ctx += 'Webcams section is open. ' + CAMS.describe() + '\nThe images themselves are not readable here.\n';

    } else if (section === 'regional') {
      var regEl = document.getElementById('section-regional');
      if (regEl) ctx += 'Nearby Observation Stations:\n' + regEl.innerText.substring(0, 12500);

    } else if (section === 'tropical') {   // v3.79.0
      var trEl = document.getElementById('section-tropical');
      if (trEl) ctx += 'National Hurricane Center (active storms, watches/warnings, Tropical Weather Outlooks):\n' + trEl.innerText.substring(0, 12500);

    } else if (section === 'astro') {
      var astroEl = document.getElementById('section-astro');
      if (astroEl) ctx += 'Sun/Moon & Astronomical Data:\n' + astroEl.innerText.substring(0, 7500);

    } else if (section === 'aqi') {
      var aq = document.getElementById('section-aqi');
      if (aq) ctx += 'Air Quality Data:\n' + aq.innerText.substring(0, 7500);

    } else if (section === 'alerts') {
      var al = document.getElementById('section-alerts');
      if (al) ctx += 'Active Weather Alerts:\n' + al.innerText.substring(0, 12500);

    } else if (section === 'spc') {
      // Grab whichever SPC sub-panel is active
      var activeSpc = document.querySelector('#section-spc .spc-panel:not(.hidden)');
      if (activeSpc) ctx += 'SPC Data:\n' + activeSpc.innerText.substring(0, 12500) + '\n';
      var spcD = document.querySelector('.spc-discuss-body[style*="block"] .spc-discuss-text');
      if (spcD) ctx += 'SPC Discussion:\n' + spcD.innerText.substring(0, 10000);
      var mesoT = document.getElementById('spcMesoTexts');
      if (mesoT && mesoT.innerText.length > 20) ctx += '\nMesoscale Discussions:\n' + mesoT.innerText.substring(0, 10000);

    } else if (section === 'cpc') {
      var cpcEl = document.getElementById('section-cpc');
      if (cpcEl) {
        // Get whichever CPC period is active
        var activeCpc = cpcEl.querySelector('.cpc-panel:not(.hidden)');
        if (activeCpc) ctx += 'CPC Outlook Period:\n' + activeCpc.innerText.substring(0, 2500) + '\n';
        // Get any open discussion
        var cpcDiscs = cpcEl.querySelectorAll('.spc-discuss-body');
        cpcDiscs.forEach(function(d) {
          if (d.style.display === 'block') {
            var txt = d.querySelector('.spc-discuss-text');
            if (txt) ctx += 'CPC Discussion:\n' + txt.innerText.substring(0, 10000) + '\n';
          }
        });
      }

    } else if (section === 'models') {
      var activePanel = document.querySelector('#section-models .gs-panel:not(.hidden)');
      if (activePanel) {
        var snap = activePanel.querySelector('[id$="Snapshot"]');
        var daily = activePanel.querySelector('[id$="DailySummary"]');
        var narr = activePanel.querySelector('[id$="Narrative"]');
        var assess = activePanel.querySelector('[id$="Assessment"]');
        var indices = activePanel.querySelector('[id$="Indices"]');
        var loading = activePanel.querySelector('[id$="Loading"]');
        if (snap && snap.innerText.trim()) ctx += 'Model Snapshot:\n' + snap.innerText.substring(0, 2500) + '\n';
        if (daily && daily.innerText.trim()) ctx += 'Daily Forecast:\n' + daily.innerText.substring(0, 10000) + '\n';
        if (narr && narr.innerText.trim()) ctx += 'Forecast Discussion:\n' + narr.innerText.substring(0, 7500) + '\n';
        if (assess && assess.innerText.trim()) ctx += 'Severe Assessment:\n' + assess.innerText.substring(0, 10000) + '\n';
        if (indices && indices.innerText.trim()) ctx += 'Sounding Indices:\n' + indices.innerText.substring(0, 2500) + '\n';
        if (loading && !loading.classList.contains('hidden')) ctx += 'Note: Model data is still loading or failed to load.\n';
        if (activePanel.id === 'gs-panel-sounding' && window.SND && SND.describe) ctx += SND.describe();
        // Also grab the model description
        var desc = activePanel.querySelector('[style*="color:var(--text-dim)"]');
        if (desc && desc.innerText.length > 30) ctx += 'Model info: ' + desc.innerText.substring(0, 1500) + '\n';
      }

    } else if (section === 'climate') {
      var climEl = document.getElementById('section-climate');
      if (climEl) ctx += 'Climate / Yesterday Summary:\n' + climEl.innerText.substring(0, 7500);
    }
  } catch(e) { ctx += '(Error gathering context: ' + e.message + ')'; }

  // Sections used to be cut at 3,000 characters and the whole at 5,000, which lost the end of long products.
  return ctx.length > 40000 ? ctx.substring(0, 40000) + '\n[The page continues past this point and was cut off here.]' : ctx;
}

// `html` must already be safe; user text goes in as plain text.
function addChatMessage(role, html, plain) {
  var msgs = document.getElementById('chatMessages');
  var div = document.createElement('div');
  div.className = 'chat-msg ' + (role === 'user' ? 'chat-user' : 'chat-ai');
  if (plain) div.textContent = html; else div.innerHTML = html;
  msgs.appendChild(div);
  msgs.scrollTop = msgs.scrollHeight;
}

async function sendChatMessage() {
  var input = document.getElementById('chatInput');
  var btn = document.getElementById('chatSendBtn');
  var msg = input.value.trim();
  if (!msg || sendChatMessage._busy) return;   // Enter used to bypass the disabled button

  var key = getClaudeKey();
  if (!key && !claudeServerKey) { addChatMessage('ai', 'The assistant is off. Add the <b>ANTHROPIC_API_KEY</b> secret in Cloudflare; Settings shows what is set.'); return; }

  addChatMessage('user', msg, true);
  input.value = '';
  btn.disabled = true;
  sendChatMessage._busy = true;
  var gen = chatGen;

  // Add thinking indicator
  var thinkDiv = document.createElement('div');
  thinkDiv.className = 'chat-msg chat-ai chat-thinking';
  thinkDiv.textContent = 'Analyzing weather data...';
  document.getElementById('chatMessages').appendChild(thinkDiv);
  document.getElementById('chatMessages').scrollTop = document.getElementById('chatMessages').scrollHeight;

  // The forecast discussion is the product questions lean on most; fetch it if its tab has not been opened yet.
  if (getActiveSection() !== 'afd' && window._afdOffice && _lazyDone.afd !== window._afdOffice) { _lazyDone.afd = window._afdOffice; try { await Promise.race([fetchAFD(window._afdOffice), new Promise(function (r) { setTimeout(r, 8000); })]); } catch (e) { /* answer without it */ } }
  var scr = await SCREEN.capture(SCREEN.picsOn()), context = scr.text, shots = scr.images;
  var others = gatherOtherTabs(getActiveSection());
  if (others) context += '\n\nOTHER TABS (loaded in the app, not on screen):' + others;
  if (context.length > 60000) context = context.slice(0, 60000) + '\n[cut off]';
  var webOn = chatWebOn();

  // Build conversation
  var systemPrompt = 'You are a weather analysis assistant embedded in NWS Terminal, a comprehensive weather app. ' +
    'You help users understand the weather data on their current screen. ' +
    'Sections include: NWS forecasts, hourly tables, Area Forecast Discussions, radar, satellite imagery, ' +
    'nearby observation stations, sun/moon data, air quality, active alerts, ' +
    'CPC extended outlooks, SPC convective outlooks and mesoscale discussions, ' +
    'model data (GFS, ECMWF IFS, HRRR, RAP, RRFS, AIFS, GraphCast, FourCastNet, NBM, GEFS ensemble), ' +
    'atmospheric soundings with severe weather indices, and climate/yesterday records. ' +
    'Be conversational but precise. Reference specific numbers from the data when available. ' +
    'When discussing severe weather, be calibrated and always recommend checking official NWS/SPC products. ' +
    'Keep responses concise (2-4 short paragraphs). Use plain English unless the user seems technical. ' +
    'The context holds everything written on the open tab and every chart on it as numbers. Pictures of the maps, radar, satellite, diagrams and images on screen are attached when the context lists them: read them directly and say what they show. ' +
    'If the context lists a visual you cannot see, say so plainly instead of guessing at it. ' +
    'For sun/moon, help with planning (golden hour, daylight, moon phase). ' +
    'For regional obs, compare nearby stations to the forecast. ' +
    'For climate, compare current conditions to normals and records. ' +
    'Format key numbers with <b> tags. ' +
    'The context gives the open tab first, then data from other tabs of the app. Use both. ' +
    (webOn ? 'You can search the web. Search only when the app data cannot answer: news, events elsewhere, products the app does not carry. ' +
             'Do not search for what is already in the context. Prefer official sources such as weather.gov, spc.noaa.gov, wpc.ncep.noaa.gov and nhc.noaa.gov.'
           : 'You cannot search the web. If a question needs outside or newer information, say so and mention the Web search switch under the chat.');

  chatHistory.push({ role: 'user', content: 'SCREEN CONTEXT:\n' + context + '\n\nUSER QUESTION: ' + msg });

  // Keep conversation manageable (last 6 exchanges), starting on a user turn.
  var trimmedHistory = chatHistory.slice(-12);
  while (trimmedHistory.length && trimmedHistory[0].role !== 'user') trimmedHistory.shift();
  trimmedHistory = trimmedHistory.map(function (m, i) { var q = i < trimmedHistory.length - 1 && m.role === 'user' && typeof m.content === 'string' ? m.content.indexOf('\n\nUSER QUESTION: ') : -1;
    return q > 0 && m.content.indexOf('Screen context:') === 0 ? { role: 'user', content: m.content.slice(q + 2) } : m; });

  try {
    var sendHist = trimmedHistory, picNote = '';
    if (shots.length && trimmedHistory.length) { var lastM = trimmedHistory[trimmedHistory.length - 1]; sendHist = trimmedHistory.slice(0, -1).concat([{ role: 'user', content: shots.concat([{ type: 'text', text: lastM.content }]) }]); }
    var onQ = function (q) { thinkDiv.textContent = 'Searching the web: ' + q.slice(0, 60); }, out;
    var onT = function (t) { if (!t) return; thinkDiv.classList.remove('chat-thinking'); thinkDiv.innerHTML = chatFormat(t); var cm = document.getElementById('chatMessages'); if (cm.scrollHeight - cm.scrollTop - cm.clientHeight < 160) cm.scrollTop = cm.scrollHeight; };
    try { out = await chatCall(key, systemPrompt, sendHist, webOn, onQ, onT); }
    catch (e1) {   // a picture the service could not take (too large, or a link it could not open): answer from the text
      if (!shots.length || !/HTTP (400|413)/.test(String(e1 && e1.message))) throw e1;
      thinkDiv.classList.add('chat-thinking'); thinkDiv.textContent = 'Analyzing weather data...';
      out = await chatCall(key, systemPrompt, trimmedHistory, webOn, onQ, onT); picNote = 'The pictures of the screen were not accepted, so this answer uses the text and numbers only.';
    }
    if (gen !== chatGen) return;   // New conversation was pressed while this one was out: drop it
    if (picNote) out.note = out.note ? out.note + ' ' + picNote : picNote;
    var data = out.data, raw = out.text;
    if (!raw) {
      raw = data.stop_reason === 'refusal' ? 'The assistant declined to answer that.'
          : data.stop_reason === 'max_tokens' ? 'The answer ran out of room before it finished. Ask again, or ask something narrower.'
          : 'The assistant returned an empty reply. Try again.';
    }
    chatHistory.push({ role: 'assistant', content: raw });
    // Escape FIRST, then apply the tiny markdown subset. The reply is built
    // from on-screen third-party text (alerts, discussions), so rendering it
    // raw let an <img onerror> run next to three stored API keys.
    var reply = chatFormat(raw);

    thinkDiv.remove();
    addChatMessage('ai', reply + chatSources(out));
  } catch(e) {
    if (gen !== chatGen) return;
    thinkDiv.remove();
    chatHistory.pop();   // don't resend the failed question with the next one
    var em = String((e && e.message) || 'error'), slow = /abort|timed? ?out|TimeoutError/i.test(em) || (e && e.name === 'TimeoutError');
    addChatMessage('ai', slow ? 'The assistant went quiet for 90 seconds and the request was stopped. Try again, or ask something narrower.' : '<b>Error:</b> ' + esc(em.substring(0, 200)));
    console.error('[CHAT]', e);
  }
  sendChatMessage._busy = false;
  btn.disabled = false;
  input.focus();
}

// Chat enter key handler registered in DOMContentLoaded above

async function gsPost(model, payload) {
  var token = getGsToken();
  if (!token && !gsServerToken) throw new Error('No GribStream token. Add the GS_TOKEN secret in Cloudflare.');
  var seq = _fetchSeq;
  var apiPath = '/api/v2/' + model + '/timeseries';
  var target = 'https://gribstream.com' + apiPath;
  var body = JSON.stringify(payload);
  var hdrs = { 'Content-Type': 'application/json', 'Accept': 'application/json' };
  if (token) hdrs.Authorization = 'Bearer ' + token;
  var hdrsNp = { 'Content-Type': 'text/plain', 'Authorization': 'Bearer ' + token };

  // Same-origin route on this worker first (no CORS, no second worker to
  // keep alive, and it can inject a server-side token), then the legacy
  // external worker, then direct.
  var proxies = [];
  if (location.protocol.indexOf('http') === 0) proxies.push({ name: 'same-origin', url: '/p/gs' + apiPath, hdrs: hdrs });
  var worker = getGsWorker();
  if (token && worker) {
    proxies.push({ name: 'worker', url: worker + apiPath, hdrs: hdrs });
  }
  // The original also tried corsproxy.io — an anonymous third-party relay —
  // with `Authorization: Bearer <your token>` in cleartext, and a proxy-index
  // mismatch made it the PREFERRED transport after a successful Test. Removed:
  // set a Worker URL in Settings if the direct request is CORS-blocked.
  if (token) proxies.push(
    { name: 'direct', url: target, hdrs: hdrs },
    { name: 'direct-np', url: target, hdrs: hdrsNp }
  );

  // If we found a working proxy before, try it first
  if (gsPost._wp >= 0 && gsPost._wp < proxies.length) {
    var wp = proxies[gsPost._wp];
    proxies = [wp].concat(proxies.filter(function(_,i){ return i !== gsPost._wp; }));
  }

  var errors = [];
  for (var i = 0; i < proxies.length; i++) {
    var p = proxies[i];
    try {
      var ctrl = new AbortController();
      var tid = setTimeout(function() { ctrl.abort(); }, 15000);
      var res = await netFetch(p.url, { method: 'POST', headers: p.hdrs, body: body, signal: ctrl.signal });
      clearTimeout(tid);
      if (res.status === 401) throw new Error('Invalid token — check your GribStream API token');
      if (res.status === 429) throw new Error('Rate limit exceeded — wait and retry');
      if (!res.ok) {
        var et = ''; try { var ej = await res.json(); et = ej.error||ej.message||ej.reason||JSON.stringify(ej).substring(0,200); } catch(e) { try { et=(await res.text()).substring(0,200); } catch(e2){et='HTTP '+res.status;} }
        throw new Error(res.status + ': ' + et);
      }
      var data = await res.json();
      try { if (typeof GSRUNS !== 'undefined') GSRUNS.note(model, data); } catch (eRun) { /* the run table is a nicety */ }
      if (data && data.error) throw new Error(data.error||data.reason||JSON.stringify(data).substring(0,200));
      if (gsPost._wp !== i) { gsPost._wp = i; console.log('[GS] Working: ' + p.name); }
      // The location changed while this was in flight. Never settle: the
      // caller's render/cache code after `await` must not run, or the old
      // city's model data lands in the new city's (freshly reset) cache.
      if (seq !== _fetchSeq) return new Promise(function () {});
      return data;
    } catch(e) {
      clearTimeout(tid);
      var msg = e.name === 'AbortError' ? 'Timeout' : (e.message||String(e));
      errors.push(p.name + ':' + msg.substring(0,60));
      console.warn('[GS] ' + p.name + ' failed:', msg);
      if (msg.indexOf('Invalid token')>=0 || msg.indexOf('Rate limit')>=0 || msg.indexOf('400:')>=0 || msg.indexOf('422:')>=0) throw e;
    }
  }
  gsPost._wp = -1;
  throw new Error(errors.join(' | '));
}
gsPost._wp = -1;

async function testGsConnection() {
  var st = document.getElementById('gsStatus');
  var token = getGsToken();
  if (!token) { st.textContent = 'NO TOKEN'; st.className = 'gs-status err'; return; }
  st.textContent = 'TESTING...'; st.className = 'gs-status';
  var apiPath = '/api/v2/gfs/timeseries';
  var target = 'https://gribstream.com' + apiPath;
  var body = JSON.stringify({
    fromTime: new Date().toISOString(),
    untilTime: new Date(Date.now() + 3600000).toISOString(),
    coordinates: [{lat:40,lon:-74,name:'test'}],
    variables: [{name:'TMP',level:'2 m above ground',alias:'t'}]
  });
  var worker = getGsWorker();
  var proxyList = [];
  if (worker) proxyList.push({ name: 'worker', url: worker + apiPath, ct: 'application/json' });
  proxyList.push(
    { name: 'direct', url: target, ct: 'application/json' },
    { name: 'direct-np', url: target, ct: 'text/plain' },
    // corsproxy.io entries removed — they carried `Authorization: Bearer <token>`
    // in cleartext to an anonymous third party.
  );
  for (var i = 0; i < proxyList.length; i++) {
    var p = proxyList[i];
    try {
      st.textContent = 'Try ' + p.name + '...';
      var ctrl = new AbortController();
      var tid = setTimeout(function() { ctrl.abort(); }, 8000);
      var hdrs = { 'Content-Type': p.ct, 'Authorization': 'Bearer ' + token };
      if (p.ct === 'application/json') hdrs['Accept'] = 'application/json';
      var res = await netFetch(p.url, { method: 'POST', headers: hdrs, body: body, signal: ctrl.signal });
      clearTimeout(tid);
      if (res.ok) {
        var d = await res.json();
        if (d && !d.error) {
          gsPost._wp = -1; /* list order differs from gsPost's; let gsPost rediscover */
          st.textContent = p.name.toUpperCase() + ' OK';
          st.className = 'gs-status ok';
          return;
        }
      } else if (res.status === 401) {
        st.textContent = 'INVALID TOKEN'; st.className = 'gs-status err'; return;
      }
    } catch(e) {
      console.warn('[GS-TEST] ' + p.name + ':', e.message);
    }
  }
  st.textContent = 'ALL FAILED'; st.className = 'gs-status err';
}

// ---- Utility ----
function kToF(k) { return k != null ? Math.round((k - 273.15) * 9/5 + 32) : null; }
function msToMph(ms) { return ms != null ? Math.round(ms * 2.237) : null; }
function fmtGsTime(iso) {
  var d = new Date(iso);
  var locOpts = { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' };
  if (locTimezone) locOpts.timeZone = locTimezone;
  var locStr = d.toLocaleString('en-US', locOpts);
  if (locTimezone) {
    var devOpts = { hour:'numeric', minute:'2-digit' };
    var devStr = d.toLocaleString('en-US', devOpts);
    var locTimeOnly = d.toLocaleString('en-US', { hour:'numeric', minute:'2-digit', timeZone: locTimezone });
    if (devStr !== locTimeOnly) {
      var devTz = _deviceTzAbbr();
      return locStr + ' <span style="color:var(--text-muted);font-size:0.85em;">(' + devStr + ' ' + devTz + ')</span>';
    }
  }
  return locStr;
}
function fmtGsTimeShort(iso) {
  var d = new Date(iso);
  var opts = { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' };
  if (locTimezone) opts.timeZone = locTimezone;
  var s = d.toLocaleString('en-US', opts);
  _gsLabelMs[s] = d.getTime();   // the chart system reads times back from labels
  return s;
}
function _deviceTzAbbr() {
  try {
    var parts = new Intl.DateTimeFormat('en-US', { timeZoneName:'short' }).formatToParts(new Date());
    var tz = parts.find(function(p) { return p.type === 'timeZoneName'; });
    return tz ? tz.value : 'your time';
  } catch(e) { return 'your time'; }
}
function fmtModelRun(data) {
  if (!data || !data.length) return '';
  var fa = data[0].forecasted_at;
  if (!fa) return '';
  var d = new Date(fa);
  var h = d.getUTCHours();
  var runZ = String(h).padStart(2,'0') + 'z';
  var locRunOpts = { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' };
  if (locTimezone) locRunOpts.timeZone = locTimezone;
  var locRunStr = d.toLocaleString('en-US', locRunOpts);
  var extra = '';
  if (locTimezone) {
    var locTimeOnly = d.toLocaleString('en-US', { hour:'numeric', minute:'2-digit', timeZone: locTimezone });
    var devTimeOnly = d.toLocaleString('en-US', { hour:'numeric', minute:'2-digit' });
    if (locTimeOnly !== devTimeOnly) {
      var devRunStr = d.toLocaleString('en-US', { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' });
      extra = ' <span style="font-size:12px;color:var(--text-muted);">(' + devRunStr + ' ' + _deviceTzAbbr() + ')</span>';
    }
  }
  return '<span style="font-size:13px;color:var(--text-muted);margin-left:8px;">' + runZ + ' run &mdash; ' + locRunStr + extra + '</span>';
}

async function gsRefresh(model) {
  try { await loadVendor('chart'); } catch (e) { return; }
  if (!currentLat || !currentLon || !gsAvailable()) return;
  var fetchMap = {
    gfs: fetchGsGfs, ecmwf: fetchGsEcmwf, hrrr15: fetchGsHrrr15,
    rap: fetchGsRap, rrfs: fetchGsRrfs, aifs: fetchGsAifs,
    graphcast: fetchGsGraphcast, fourcast: fetchGsFourcast,
    nbm: fetchGsNbm, ensemble: fetchGsEnsemble, rtma: fetchGsRtma,
    verify: fetchGsVerify, sounding: fetchGsSounding, severe: fetchGsSevere, thunder: fetchGsThunder, odds: fetchGsOdds, trend: fetchGsTrend
  };
  gsDataCache[model] = null;
  if (fetchMap[model]) fetchMap[model](currentLat, currentLon);
}

function destroyGsChart(id) { if (gsCharts[id]) { gsCharts[id].destroy(); delete gsCharts[id]; } }

/* ══════════════════════════════════════════════════════════════════
   MODEL CHART SYSTEM (v3.3.0)
   Every model chart is drawn by makeGsLineChart / makeGsBarChart, so the
   look lives here once:
   - hour-only ticks on round local hours, with the date under each new day
   - night shading (sun below the horizon at the forecast point), a dashed
     line at each local midnight, a 32° line on temperature charts, "now"
   - the last value written at the end of each line, in the line's colour
   - one crosshair shared by every chart in the open model tab
   - monotone interpolation: a curve never overshoots the data
   - a series that is zero throughout collapses to one line of text
   Charts get their timestamps from fmtGsTimeShort (label -> ms), so no
   call site had to change.
   ══════════════════════════════════════════════════════════════════ */
var _gsLabelMs = Object.create(null);
var GS_MONO = "Inter, system-ui, sans-serif";   // v3.58.0: chart figures in the page font
