      var by = {}; (rows || []).forEach(function (r) { var t = Date.parse(r.forecasted_time); (by[t] || (by[t] = [])).push(r); });
      return times.map(function (t) { return gridFrom(Lt, by[t] || [], function (r) { return +r.c; }, true); });
