    function xy(lat, lon) { var dl = ((lon + 97.5) % 360 + 540) % 360 - 180, r = RE * FF / Math.pow(Math.tan(Math.PI / 4 + lat * DG / 2), N), th = N * dl * DG; return [r * Math.sin(th), -r * Math.cos(th)]; }
