    var t = (el.innerText || el.textContent || '').replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
    if (t.length < 60 || /Loading [A-Za-z ]{0,30}(\.\.\.|…)/.test(t.slice(0, 300))) return;   // not loaded yet
