    ctx.font = '600 11.5px ' + GS_MONO; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.lineJoin = 'round'; ctx.lineWidth = 3; ctx.strokeStyle = GS_C.surface;
    ctx.strokeText(e.txt, e.x, ly); ctx.fillStyle = GS_C.strong; ctx.fillText(e.txt, e.x, ly);
