    for (var i2 = 1; i2 < items.length; i2++) if (items[i2].y - items[i2 - 1].y < 15) items[i2].y = items[i2 - 1].y + 15;
    for (var k = items.length - 1; k >= 0; k--) { var cap = a.bottom - (items.length - 1 - k) * 15; if (items[k].y > cap) items[k].y = cap; }
