    if (sndRow && grid) pop.querySelector('.map-pop-body').style.maxHeight = Math.max(110, Math.min(440, R.height - 44 - sndRow.offsetHeight - 8)) + 'px';   // v3.61.0
    pop._x = cx - R.left; pop._y = cy - R.top;
