    var t = e.target, g = t.closest ? t.closest('.regmap-stn') : null, stage = t.closest ? t.closest('.regmap-stage') : null;
    if (t.closest && t.closest('.map-pop')) { if (t.closest('.map-pop-x')) close(stage); return; }
    if (!stage) return;
