    var newest = d.obs && d.obs.length ? Math.max.apply(null, d.obs.map(function (x) { return x.t; })) : 0;
    if (on.stn) say(d.obs, d.obs ? S.shown + ' of ' + d.obs.length + ' stations shown' + (Date.now() - newest > 75 * MIN ? ' (reports from ' + clock(newest) + ': nothing newer came back)' : '') : '', 'obs', 'Stations');
