    if (on.pres || on.temp) say(d.rap, d.rap ? 'Isobars and temperature: RAP model for ' + clock(d.rap.t) + (Date.now() - d.rap.t > 100 * MIN ? ' (an older hour; the newest did not load)' : '') : '', 'rap', 'Isobars and temperature');
    if (on.warn) say(d.warn, d.warn ? (d.warn.length ? d.warn.length + ' warning' + (d.warn.length === 1 ? '' : 's') + ' in force' : 'No warnings in force') : '', 'warn', 'Warnings');
