  function go(q, fav) { if (!q) return; if (fav && typeof loadFavorite === 'function') loadFavorite(q); else { document.getElementById('locationInput').value = q; doFetch(); } }
  function init() {
    var root = document.getElementById('homeEl'); if (!root) return; var stage = root.querySelector('.usn-stage'), det = root.querySelector('.regmap-detail');
    stage.addEventListener('click', function (e) {
      var t = e.target, ob = t.closest('[data-open]'); if (ob) { go(ob.getAttribute('data-open'), false); return; }
      if (t.closest('.map-pop')) return;
      var f = t.closest('.usn-fav'); if (f) { go(f.getAttribute('data-q'), f.getAttribute('data-fav') === '1'); return; }
      var g = t.closest('.regmap-stn'); if (!g) return;
      if (g.hasAttribute('data-bg')) { var r = stage.getBoundingClientRect(); det.innerHTML = spotDetail((e.clientX - r.left) / r.width * W, (e.clientY - r.top) / r.height * H); }
      else det.innerHTML = S.taps[+g.getAttribute('data-i')] || '';
    });
    stage.addEventListener('keydown', function (e) { if (e.key !== 'Enter' && e.key !== ' ') return; var f = e.target.closest && e.target.closest('.usn-fav'); if (f) { e.preventDefault(); go(f.getAttribute('data-q'), f.getAttribute('data-fav') === '1'); return; }
      var g = e.target.closest && e.target.closest('.regmap-stn'); if (g && !g.hasAttribute('data-bg')) det.innerHTML = S.taps[+g.getAttribute('data-i')] || ''; });
    det.addEventListener('click', function (e) { var ob = e.target.closest('[data-open]'); if (ob) go(ob.getAttribute('data-open'), false); });
    root.querySelector('.usn-layers').addEventListener('click', function (e) { var b = e.target.closest('[data-ly]'); if (!b) return; var k = b.getAttribute('data-ly'); on[k] = !on[k]; lsSet('usnow_layers', JSON.stringify(on)); chips(root); if (S.base) { draw(); reload(false); } });
    root.querySelector('.usn-places').addEventListener('click', function (e) { var b = e.target.closest('.usn-place'); if (b) go(b.getAttribute('data-q'), b.getAttribute('data-fav') === '1'); });
    var rb = root.querySelector('[data-usn-refresh]'); if (rb) rb.addEventListener('click', function () { if (S.base) reload(true); else show(true); });
    var rt = null; window.addEventListener('resize', function () { if (!S.on || !S.base) return; clearTimeout(rt); rt = setTimeout(draw, 180); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
