    var fold = row.classList.contains('pick-fold'), left = fold ? Math.max(0, Math.round(parseFloat(getComputedStyle(host).paddingLeft) || 0)) : Math.round(rr.left - hr.left);   // a folded row is only as wide as its button: the list takes the width of the card it sits in
    p.style.top = Math.round(rr.bottom - hr.top + 6) + 'px'; p.style.left = left + 'px'; p.style.width = Math.round(fold ? Math.min(920, host.clientWidth - 2 * left) : rr.width) + 'px';
    p.style.maxHeight = Math.max(220, Math.round(window.innerHeight - rr.bottom - 24)) + 'px';
