    var row = b.closest('.pick-row') || b.parentNode, rr = row.getBoundingClientRect(), tb = document.querySelector('.topbar'), floor = (tb ? tb.getBoundingClientRect().bottom : 0) + 8, short = p.scrollHeight - (window.innerHeight - rr.bottom - 24);
    if (short > 0 && rr.top > floor) { try { window.scrollBy({ top: Math.min(short, rr.top - floor), behavior: 'instant' }); } catch (e) { window.scrollBy(0, Math.min(short, rr.top - floor)); } place(id); }
